mapper.select:
SELECT billRefundRecordId, refundDate, orderDate, orgId, billId, billNum, patientId, patientName, gender, mobile, treatmentId, regDentistId, regDentistName, actualAmount, receivedAmount, refundAmount, refundOperatorId, refundOperatorName, refundReason FROM ( SELECT br.refund_id AS billRefundRecordId, DATE_FORMAT(br.refund_date, '%Y-%m-d%') AS refundDate, DATE_FORMAT( bb.order_date, '%Y-%m-%d' ) AS orderDate, DATE_FORMAT( bb.bill_date, '%Y-%m-%d' ) AS billDate, br.org_id AS orgId, br.bill_id AS billId, bb.bill_num AS billNum, br.patient_id AS patientId, bp.`name` AS patientName, bp.pinyin_name AS pinyinName, bp.gender AS gender, bp.mobile AS mobile, br.treatment_id AS treatmentId, btp.registered_dentist_id AS regDentistId, btp.regDentistName AS regDentistName, bb.actual_amount AS actualAmount, bb.received_amount AS receivedAmount, br.refund_amount AS refundAmount, br.refund_opterator_id AS refundOperatorId, be.employee_name AS refundOperatorName, br.refund_reason AS refundReason FROM base_refund br LEFT JOIN base_patient bp ON br.patient_id = bp.patient_id LEFT JOIN ( SELECT btp.treatment_id, btp.registered_dentist_id, be.employee_name AS regDentistName FROM base_treatment_process btp LEFT JOIN base_employee be ON btp.registered_dentist_id = be.user_id ) btp ON br.treatment_id = btp.treatment_id LEFT JOIN base_bill bb ON br.bill_id = bb.bill_id LEFT JOIN base_employee be ON br.refund_opterator_id = be.user_id ) br
and br.orgId = #{orgId}
and concat(ifnull(br.patientName, ''), ifnull(br.pinyinName, ''), ifnull(br.mobile, '')) like concat('%', #{query.keyWord}, '%')
and br.billNum = #{query.billNum}
and br.refundDate >= #{query.refundStartDate}
and br.refundDate <= #{query.refundEndDate}
and br.billDate >= #{query.billStartDate}
and br.billDate <= #{query.billEndDate}
and br.regDentistId in
#{item}
order by br.refundDate desc
